 	<li>
<p class="zw-list zw-paragraph heading0" data-header="0" data-textformat="{&quot;fgc&quot;:&quot;rgb(0, 0, 0)&quot;,&quot;size&quot;:&quot;12.00&quot;,&quot;type&quot;:&quot;text&quot;}" data-margin-left="0.5in" data-text-indent="-0.25in" data-margin-bottom="0pt" data-hd-info="0" data-line-height="1.2" data-list-id="61091390" data-list-info="{&quot;id&quot;:&quot;61091390&quot;,&quot;l&quot;:0}">Planejamento Estratégico</p>
